.hub-hero { position: relative; background: linear-gradient(135deg, #0a1120 0%, #101a35 50%, #0f172a 100%); color: #fff; padding: 80px 0 60px; text-align: center; overflow: hidden; }
.hub-hero::before { content: ''; position: absolute; inset: 0; background-image: linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px); background-size: 56px 56px; pointer-events: none; }
.hub-hero > .container { position: relative; z-index: 2; }
.hub-hero .kicker { display: inline-block; font-size: 11px; font-weight: 800; letter-spacing: 1.6px; text-transform: uppercase; color: #bfdbfe; background: rgba(30,64,175,0.20); border: 1px solid rgba(30,64,175,0.45); padding: 6px 14px; border-radius: 30px; margin-bottom: 18px; }
.hub-hero h1 { font-size: 44px; font-weight: 900; line-height: 1.15; color: #fff; margin: 0 auto 18px; max-width: 900px; letter-spacing: -0.5px; }
.hub-hero h1 .grad { background: linear-gradient(135deg, #1e40af 0%, #7c3aed 50%, #ec4899 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; color: transparent; }
.hub-hero .sub { font-size: 17px; line-height: 1.65; color: rgba(255,255,255,0.85); max-width: 880px; margin: 0 auto 26px; }
.hub-sec { padding: 68px 0; }
.hub-row { margin-bottom: 44px; padding-bottom: 44px; border-bottom: 1px dashed #e2e8f0; }
.hub-row:last-child { border-bottom: none; margin-bottom: 0; padding-bottom: 0; }
.hub-city-header { display: flex; gap: 20px; align-items: center; margin-bottom: 22px; }
.hub-flag { font-size: 42px; line-height: 1; }
.hub-city-header h3 { font-size: 24px; font-weight: 800; color: #0f172a; margin: 0 0 4px; }
.hub-city-header p { font-size: 13.5px; color: #64748b; margin: 0; line-height: 1.5; }
.hub-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 14px; }
.hub-card { position: relative; padding: 22px 20px; background: #fff; border: 1px solid #e2e8f0; border-radius: 14px; text-decoration: none !important; color: inherit; transition: transform .2s ease, border-color .2s ease, box-shadow .2s ease; overflow: hidden; }
.hub-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: linear-gradient(90deg, var(--c1), var(--c2)); opacity: 0; transition: opacity .2s ease; }
.hub-card:hover { transform: translateY(-3px); border-color: var(--c1); box-shadow: 0 14px 30px rgba(15,23,42,0.10); }
.hub-card:hover::before { opacity: 1; }
